+    <script>
+      (function () {
+        const body = document.body;
+
+        // Smooth scroll (lightweight)
+        document.querySelectorAll('[data-scroll]').forEach((el) => {
+          el.addEventListener('click', (e) => {
+            const href = el.getAttribute('href');
+            if (!href || !href.startsWith('#')) return;
+            const target = document.querySelector(href);
+            if (!target) return;
+            e.preventDefault();
+            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
+          });
+        });
+
+        // Mobile drawer (required interaction)
+        const drawer = document.querySelector('[data-drawer]');
+        const backdrop = document.querySelector('[data-drawer-backdrop]');
+        const openBtn = document.querySelector('[data-drawer-open]');
+        const closeBtn = document.querySelector('[data-drawer-close]');
+        const drawerLinks = document.querySelectorAll('[data-drawer-link]');
+        const setDrawer = (isOpen) => {
+          body.classList.toggle('drawerOpen', isOpen);
+          if (drawer) drawer.setAttribute('aria-hidden', String(!isOpen));
+          if (openBtn) openBtn.setAttribute('aria-expanded', String(isOpen));
+          if (isOpen) {
+            // trap initial focus lightly
+            const focusable = drawer?.querySelector('a,button');
+            focusable?.focus();
+          } else {
+            openBtn?.focus();
+          }
+        };
+        openBtn?.addEventListener('click', () => setDrawer(true));
+        closeBtn?.addEventListener('click', () => setDrawer(false));
+        backdrop?.addEventListener('click', () => setDrawer(false));
+        drawerLinks.forEach((a) => a.addEventListener('click', () => setDrawer(false)));
+        window.addEventListener('keydown', (e) => {
+          if (e.key === 'Escape') setDrawer(false);
+        });
+
+        // Search interactions
+        const form = document.querySelector('[data-search-form]');
+        const queryInput = document.querySelector('[data-autocomplete]');
+        const suggestionsEl = document.querySelector('[data-suggestions]');
+        const locationInput = document.querySelector('[data-location]');
